window.kbPageData["views/entry/k-b7753c6601e5bab7"] = {"key":"entry/k-b7753c6601e5bab7","state":{"route":"entry/k-b7753c6601e5bab7"},"node":{"id":"k-b7753c6601e5bab7","mode":"k","title":"重大工程项目","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["industry"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"（三）重大工程项目\n围绕推动“十五五”目标任务落实落地，统筹考虑战略性、牵引性和连续性，《纲要（草\n案）》提出 6 方面 109 项重大工程。引领新质生产力发展方面，围绕产业基础能力和竞争力\n提升、新产业新赛道①培育发展、前沿科技攻关、创新基础能力提升提出 28 项工程。构建现\n代化基础设施体系方面…","sources":[{"id":"0ec4b35ee5891b6c","label":"重大工程项目","topic":"年度政府工作","category":"时政","text":"（三）重大工程项目\n围绕推动“十五五”目标任务落实落地，统筹考虑战略性、牵引性和连续性，《纲要（草\n案）》提出 6 方面 109 项重大工程。引领新质生产力发展方面，围绕产业基础能力和竞争力\n提升、新产业新赛道①培育发展、前沿科技攻关、创新基础能力提升提出 28 项工程。构建现\n代化基础设施体系方面，围绕国家综合立体交通网、新型能源体系②、新型基础设施③、对\n外开放平台等提出 23 项工程。促进城乡融合发展方面，围绕新型城镇化建设、农业农村现\n代化建设提出 9 项工程。保障和改善民生方面，围绕社会主义文化繁荣发展、高质量教育体\n系建设、健康中国建设、优化“一老一小”服务、社会关爱服务提出 25 项工程。推动绿色\n低碳转型方面，围绕碳达峰碳中和、环境质量提升、生态保护修复提出 18 项工程。重点领\n域安全保障方面，围绕粮食、能源安全等提出 6 项工程。这些重大工程兼顾当前和长远，既\n涉及“硬投资”④也包含“软建设”⑤。我们将注重以政府投资带动社会力量参与，更好发挥\n重大工程项目强基础、补短板、增后劲等重要作用。\n展望未来，我们充满信心。在以习近平同志为核心的党中央坚强领导下，全国上下团结\n奋斗，一定能够把“十五五”宏伟蓝图变成美好现实。","source":{"doc":"6cbfb01fe723bba64b75","first":20,"last":20,"page":20,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-b7753c6601e5bab7":[]}};
